pub fn parse_csv_line(line: Str) -> Result[List[Str], Str] {
  let cs = line.chars()
  let n = cs.len()
  var fields: List[Str] = []
  var cur = ""
  var inq = false
  var i = 0
  while i < n {
    let c = cs.get_or(i, "")
    if inq {
      if c == "\"" {
        if cs.get_or(i + 1, "") == "\"" {
          cur = cur + "\""
          i = i + 1
        } else {
          inq = false
        }
      } else {
        cur = cur + c
      }
    } else {
      if c == "\"" {
        inq = true
      } else if c == "," {
        fields = fields.push(cur)
        cur = ""
      } else {
        cur = cur + c
      }
    }
    i = i + 1
  }
  if inq {
    return Err("unterminated quote")
  }
  fields = fields.push(cur)
  return Ok(fields)
}
